mapper.sql:
SELECT DISTINCT deviceId AS deviceId, LOWER(deviceNumber) AS deviceNumber, searchPriority, sortingValue
FROM
(
SELECT
       devices.id AS deviceId,
       devices.number AS deviceNumber,

(
    COALESCE(CASE WHEN devices.number ILIKE #{value} THEN 16 END, 0) +
    COALESCE(CASE WHEN devices.imei ILIKE #{value} THEN 8 END, 0) +
    COALESCE(CASE WHEN devices.phone ILIKE #{value} THEN 4 END, 0) +
    COALESCE(CASE WHEN devices.description ILIKE #{value} THEN 2 END, 0)
    )

0
AS searchPriority,
(
    CASE
        WHEN 'STATUS' = #{sortBy} THEN
            (CASE
                WHEN (EXTRACT(EPOCH FROM NOW()) * 1000 - devices.lastupdate) < (2 * 3600 * 1000) THEN '1_green'
                WHEN (EXTRACT(EPOCH FROM NOW()) * 1000 - devices.lastupdate) < (4 * 3600 * 1000) THEN '2_yellow'
                ELSE '3_red'
            END)::VARCHAR(100)
        WHEN 'LAST_UPDATE' = #{sortBy} THEN devices.lastUpdate::VARCHAR(100)
        WHEN 'NUMBER' = #{sortBy} THEN LOWER(devices.number)::VARCHAR(100)
        WHEN 'IMEI' = #{sortBy} THEN mdm_resolve_device_property(devices.imei, devices.infojson ->> 'imei')::VARCHAR(100)
        WHEN 'PHONE' = #{sortBy} THEN mdm_resolve_device_property(devices.phone, devices.infojson ->> 'phone')::VARCHAR(100)
        WHEN 'MODEL' = #{sortBy} THEN LOWER(devices.infojson ->> 'model')::VARCHAR(100)
        WHEN 'PERMISSIONS' = #{sortBy} THEN mdm_device_permissions_index(devices.info)::VARCHAR(100)
        WHEN 'INSTALLATIONS' = #{sortBy} THEN COALESCE(deviceStatuses.applicationsStatus, 'FAILURE')::VARCHAR(100)
        WHEN 'FILES' = #{sortBy} THEN COALESCE(deviceStatuses.configFilesStatus, 'OTHER')::VARCHAR(100)
        WHEN 'CONFIGURATION' = #{sortBy} THEN LOWER(configurations.name)::VARCHAR(100)
        WHEN 'DESCRIPTION' = #{sortBy} THEN LOWER(COALESCE(devices.description, ''))::VARCHAR(100)
        WHEN 'GROUP' = #{sortBy} THEN COALESCE(LOWER(groups.name), '')::VARCHAR(100)
        WHEN 'LAUNCHER_VERSION' = #{sortBy} THEN mdm_device_launcher_version(applications.pkg, devices.info)::VARCHAR(100)
        WHEN 'BATTERY_LEVEL' = #{sortBy} THEN LPAD(COALESCE(devices.infojson ->> 'batteryLevel', '0'), 3, '0')::VARCHAR(100)
        WHEN 'DEFAULT_LAUNCHER' = #{sortBy} THEN COALESCE(devices.infojson ->> 'defaultLauncher', 'unknown')::VARCHAR(100)
        WHEN 'MDM_MODE' = #{sortBy} THEN COALESCE(devices.infojson ->> 'mdmMode', '')::VARCHAR(100)
        WHEN 'KIOSK_MODE' = #{sortBy} THEN COALESCE(devices.infojson ->> 'kioskMode', '')::VARCHAR(100)
        WHEN 'ANDROID_VERSION' = #{sortBy} THEN COALESCE(devices.infojson ->> 'androidVersion', '')::VARCHAR(100)
        WHEN 'ENROLLMENT_DATE' = #{sortBy} THEN devices.enrollTime::VARCHAR(100)
        WHEN 'SERIAL' = #{sortBy} THEN COALESCE(devices.infojson ->> 'serial', '')::VARCHAR(100)
        WHEN 'PUBLICIP' = #{sortBy} THEN COALESCE(devices.publicIp, '')::VARCHAR(100)
        WHEN 'CUSTOM1' = #{sortBy} THEN LOWER(devices.custom1)::VARCHAR(100)
        WHEN 'CUSTOM2' = #{sortBy} THEN LOWER(devices.custom2)::VARCHAR(100)
        WHEN 'CUSTOM3' = #{sortBy} THEN LOWER(devices.custom3)::VARCHAR(100)
        ELSE ''
    END
) AS sortingValue
FROM devices
INNER JOIN users ON users.id = #{userId}
LEFT JOIN deviceStatuses ON devices.id = deviceStatuses.deviceId
LEFT JOIN configurations ON devices.configurationId = configurations.id
LEFT JOIN applicationVersions ON configurations.mainAppId = applicationVersions.id
LEFT JOIN applications ON applications.id = applicationVersions.applicationid
LEFT JOIN deviceGroups ON devices.id = deviceGroups.deviceId
LEFT JOIN groups ON deviceGroups.groupId = groups.id
LEFT JOIN userDeviceGroupsAccess access ON groups.id = access.groupId AND access.userId = users.id
WHERE devices.customerId = #{customerId}
AND (users.allDevicesAvailable = TRUE OR NOT access.id IS NULL)

    AND (
    devices.number ILIKE #{value}
    OR devices.description ILIKE #{value}
    OR devices.imei ILIKE #{value}
    OR devices.phone ILIKE #{value}
    OR devices.publicIp ILIKE #{value}
    OR devices.infojson ->> 'imei' ILIKE #{value}
    OR devices.infojson ->> 'phone' ILIKE #{value}
    OR devices.infojson ->> 'model' ILIKE #{value}
    OR devices.infojson ->> 'serial' ILIKE #{value}
    OR devices.custom1 ILIKE #{value}
    OR devices.custom2 ILIKE #{value}
    OR devices.custom3 ILIKE #{value}
    OR devices.oldNumber ILIKE #{value}
    OR configurations.name ILIKE #{value}
    OR groups.name ILIKE #{value}
    )


    AND (
    devices.number = #{value}
    OR devices.fastSearch = #{value}
    )


    AND devices.imeiUpdateTs / 1000 > extract(epoch from (now() - interval '1 hour'))


    AND (
    groups.id = #{groupId}
    )


    AND (
    configurations.id = #{configurationId}
    )


    AND (
    devices.lastUpdate >= #{dateFromMillis}
    )


    AND (
    devices.lastUpdate <= #{dateToMillis}
    )


    AND (
    devices.lastUpdate <= extract(epoch from now()) * 1000 - #{onlineEarlierMillis}
    )


    AND (
    devices.lastUpdate >= extract(epoch from now()) * 1000 - #{onlineLaterMillis}
    )


    AND (
    devices.enrollTime >= #{enrollmentDateFromMillis}
    )


    AND (
    devices.enrollTime <= #{enrollmentDateToMillis}
    )


    AND (
    (devices.infojson ->> 'mdmMode')::BOOLEAN = #{mdmMode}
    )


    AND (
    (devices.infojson ->> 'kioskMode')::BOOLEAN = #{kioskMode}
    )


    AND (
    devices.infojson ->> 'androidVersion' = #{androidVersion}
    )


    AND (
    mdm_device_launcher_version(applications.pkg, devices.info) = #{launcherVersion}
    )


    AND (
    deviceStatuses.applicationsStatus = #{installationStatus}
    )

) allowedDevicesInner
ORDER BY sortingValue DESC,
         searchPriority, LOWER(deviceNumber)
OFFSET (#{pageNum} - 1) * #{pageSize}
LIMIT #{pageSize}

mapper.select:
SELECT COUNT(DISTINCT devices.id) AS counter
FROM devices
INNER JOIN users ON users.id = #{userId}
LEFT JOIN deviceStatuses ON devices.id = deviceStatuses.deviceId
LEFT JOIN configurations ON devices.configurationId = configurations.id
LEFT JOIN applicationVersions ON configurations.mainAppId = applicationVersions.id
LEFT JOIN applications ON applications.id = applicationVersions.applicationid
LEFT JOIN deviceGroups ON devices.id = deviceGroups.deviceId
LEFT JOIN groups ON deviceGroups.groupId = groups.id
LEFT JOIN userDeviceGroupsAccess access ON groups.id = access.groupId AND access.userId = users.id
WHERE devices.customerId = #{customerId}
AND (users.allDevicesAvailable = TRUE OR NOT access.id IS NULL)

    AND (
    devices.number ILIKE #{value}
    OR devices.description ILIKE #{value}
    OR devices.imei ILIKE #{value}
    OR devices.phone ILIKE #{value}
    OR devices.publicIp ILIKE #{value}
    OR devices.infojson ->> 'imei' ILIKE #{value}
    OR devices.infojson ->> 'phone' ILIKE #{value}
    OR devices.infojson ->> 'model' ILIKE #{value}
    OR devices.infojson ->> 'serial' ILIKE #{value}
    OR devices.custom1 ILIKE #{value}
    OR devices.custom2 ILIKE #{value}
    OR devices.custom3 ILIKE #{value}
    OR devices.oldNumber ILIKE #{value}
    OR configurations.name ILIKE #{value}
    OR groups.name ILIKE #{value}
    )


    AND (
    devices.number = #{value}
    OR devices.fastSearch = #{value}
    )


    AND devices.imeiUpdateTs / 1000 > extract(epoch from (now() - interval '1 hour'))


    AND (
    groups.id = #{groupId}
    )


    AND (
    configurations.id = #{configurationId}
    )


    AND (
    devices.lastUpdate >= #{dateFromMillis}
    )


    AND (
    devices.lastUpdate <= #{dateToMillis}
    )


    AND (
    devices.lastUpdate <= extract(epoch from now()) * 1000 - #{onlineEarlierMillis}
    )


    AND (
    devices.lastUpdate >= extract(epoch from now()) * 1000 - #{onlineLaterMillis}
    )


    AND (
    devices.enrollTime >= #{enrollmentDateFromMillis}
    )


    AND (
    devices.enrollTime <= #{enrollmentDateToMillis}
    )


    AND (
    (devices.infojson ->> 'mdmMode')::BOOLEAN = #{mdmMode}
    )


    AND (
    (devices.infojson ->> 'kioskMode')::BOOLEAN = #{kioskMode}
    )


    AND (
    devices.infojson ->> 'androidVersion' = #{androidVersion}
    )


    AND (
    mdm_device_launcher_version(applications.pkg, devices.info) = #{launcherVersion}
    )


    AND (
    deviceStatuses.applicationsStatus = #{installationStatus}
    )

WITH visibleDevices AS ( SELECT DISTINCT devices.id AS deviceId FROM devices INNER JOIN users ON users.id = #{userId} LEFT JOIN configurations ON devices.configurationId = configurations.id LEFT JOIN deviceGroups ON devices.id = deviceGroups.deviceId LEFT JOIN groups ON deviceGroups.groupId = groups.id LEFT JOIN userDeviceGroupsAccess access ON groups.id = access.groupId AND access.userId = users.id WHERE devices.customerId = #{customerId} AND (users.allDevicesAvailable = TRUE OR NOT access.id IS NULL)
AND groups.id = #{groupId}
AND configurations.id = #{configurationId}
), checkedApps AS ( SELECT ca.configurationId, a.pkg FROM configurationApplications ca INNER JOIN applicationVersions av ON av.id = ca.applicationVersionId INNER JOIN applications a ON a.id = av.applicationId INNER JOIN applicationVersions lv ON lv.applicationId = a.id AND lv.id = a.latestVersion INNER JOIN customers c ON c.id = a.customerId WHERE (a.customerId = #{customerId} OR c.master AND NOT EXISTS ( SELECT 1 FROM applications a2 INNER JOIN applicationVersions v2 ON v2.applicationId = a2.id WHERE a2.customerId = #{customerId} AND a2.pkg = a.pkg AND v2.version = av.version)) AND av.url IS NOT NULL AND av.url <> '' AND COALESCE(ca.action, 0) <> 2 ), deviceRows AS ( SELECT d.id, d.lastUpdate, d.configurationId, cfg.permissive, CASE WHEN d.info IS NULL OR TRIM(d.info) = '' THEN NULL ELSE d.infojson END AS info FROM visibleDevices v INNER JOIN devices d ON d.id = v.deviceId INNER JOIN configurations cfg ON cfg.id = d.configurationId ), deviceChecks AS ( SELECT r.lastUpdate, r.info IS NULL AS noInfo, (COALESCE(r.info ->> 'kioskMode', '') = 'true' OR r.permissive IS TRUE) AS permissionsSkipped, COALESCE(jsonb_typeof(r.info -> 'permissions') = 'array', FALSE) AS hasPermissions, COALESCE(jsonb_typeof(r.info -> 'permissions') = 'array' AND jsonb_array_length(r.info -> 'permissions') >= 3 AND COALESCE((r.info -> 'permissions' ->> 0)::numeric, 0) + COALESCE((r.info -> 'permissions' ->> 1)::numeric, 0) + COALESCE((r.info -> 'permissions' ->> 2)::numeric, 0) = 0, FALSE) AS noPermissions, EXISTS ( SELECT 1 FROM checkedApps ca WHERE ca.configurationId = r.configurationId AND NOT EXISTS ( SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(r.info -> 'applications') = 'array' THEN r.info -> 'applications' ELSE '[]'::jsonb END) e WHERE e ->> 'pkg' = ca.pkg) ) AS appMissing, EXISTS ( SELECT 1 FROM configurationFiles cf LEFT JOIN uploadedFiles f ON f.id = cf.fileId WHERE cf.configurationId = r.configurationId AND cf.remove = FALSE AND NOT EXISTS ( SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(r.info -> 'files') = 'array' THEN r.info -> 'files' ELSE '[]'::jsonb END) e WHERE e ->> 'path' = COALESCE(cf.devicePath, f.devicePath)) ) AS fileMissing FROM deviceRows r ) SELECT COUNT(*) AS total, COUNT(*) FILTER (WHERE (EXTRACT(EPOCH FROM NOW()) * 1000 - lastUpdate) < (2 * 3600 * 1000)) AS online, COUNT(*) FILTER (WHERE (EXTRACT(EPOCH FROM NOW()) * 1000 - lastUpdate) >= (2 * 3600 * 1000) AND (EXTRACT(EPOCH FROM NOW()) * 1000 - lastUpdate) < (4 * 3600 * 1000)) AS idle, COUNT(*) FILTER (WHERE lastUpdate IS NULL OR (EXTRACT(EPOCH FROM NOW()) * 1000 - lastUpdate) >= (4 * 3600 * 1000)) AS offline, COUNT(*) FILTER (WHERE noInfo OR (permissionsSkipped AND (appMissing OR fileMissing)) OR (NOT permissionsSkipped AND hasPermissions AND (noPermissions OR appMissing OR fileMissing))) AS needsAttention FROM deviceChecks

SELECT COUNT(DISTINCT devices.id) AS counter
FROM devices
INNER JOIN users ON users.id = #{userId}
LEFT JOIN deviceStatuses ON devices.id = deviceStatuses.deviceId
LEFT JOIN deviceGroups ON devices.id = deviceGroups.deviceId
LEFT JOIN groups ON deviceGroups.groupId = groups.id
LEFT JOIN userDeviceGroupsAccess access ON groups.id = access.groupId AND access.userId = users.id
WHERE devices.customerId = #{customerId}

    AND deviceStatuses.configFilesStatus = #{fileStatus}


    AND deviceStatuses.applicationsStatus = #{appStatus}


    AND devices.enrollTime > #{minEnrollTime}


    AND devices.enrollTime < #{maxEnrollTime}


    AND devices.lastUpdate > #{minOnlineTime}


    AND devices.lastUpdate < #{maxOnlineTime}

AND (users.allDevicesAvailable = TRUE OR NOT access.id IS NULL);

SELECT COUNT(DISTINCT devices.id) AS counter, configurations.id, configurations.name
FROM devices
INNER JOIN users ON users.id = #{userId}
LEFT JOIN configurations on devices.configurationId = configurations.id
LEFT JOIN deviceStatuses ON devices.id = deviceStatuses.deviceId
LEFT JOIN deviceGroups ON devices.id = deviceGroups.deviceId
LEFT JOIN groups ON deviceGroups.groupId = groups.id
LEFT JOIN userDeviceGroupsAccess access ON groups.id = access.groupId AND access.userId = users.id
WHERE devices.customerId = #{customerId}

    AND deviceStatuses.configFilesStatus = #{fileStatus}


    AND deviceStatuses.applicationsStatus = #{appStatus}


    AND devices.enrollTime > #{minEnrollTime}


    AND devices.enrollTime < #{maxEnrollTime}


    AND devices.lastUpdate > #{minOnlineTime}


    AND devices.lastUpdate < #{maxOnlineTime}


    AND configurations.id IN (#{configIds})

AND (users.allDevicesAvailable = TRUE OR NOT access.id IS NULL)
GROUP BY configurations.id
ORDER BY counter DESC
LIMIT 5;

SELECT searchRsults.*
FROM (
         SELECT devices.id     AS id,
                devices.number AS name,
                devices.imei   AS imei,
                devices.info   AS info,
                (
                        COALESCE(CASE WHEN devices.number ILIKE #{filter} THEN 4 END, 0) +
                        COALESCE(CASE WHEN devices.imei ILIKE #{filter} THEN 2 END, 0) +
                        COALESCE(
                                CASE WHEN devices.infojson ->> 'imei' ILIKE #{filter} THEN 1 END,
                                0)
                    )          AS searchPriority
         FROM devices
                  INNER JOIN users ON users.id = #{userId}
         WHERE devices.customerId = #{customerId}
           AND (users.allDevicesAvailable = TRUE
             OR
                EXISTS(SELECT 1
                       FROM deviceGroups
                                INNER JOIN userDeviceGroupsAccess access
                                           ON deviceGroups.groupId = access.groupId AND access.userId = users.id
                       WHERE devices.id = deviceGroups.deviceId
                    )
             )
           AND (
                 devices.number ILIKE #{filter}
                 OR devices.imei ILIKE #{filter}
                 OR devices.infojson ->> 'imei' ILIKE #{filter}
             )
         ORDER BY searchPriority DESC
     ) searchRsults
ORDER BY searchRsults.searchPriority DESC, searchRsults.name
LIMIT #{limit};

SELECT groups.*
FROM groups
INNER JOIN users ON users.id = #{userId}
LEFT JOIN userDeviceGroupsAccess access ON groups.id = access.groupId AND access.userId = users.id
WHERE groups.customerId=#{customerId}
AND groups.name ILIKE #{value}
AND (users.allDevicesAvailable = TRUE OR NOT access.id IS NULL)
ORDER BY name
